import { useId } from 'react'

/** The LapRemote mark (same drawing as the app icons generated by scripts/make_icons.py). */
export function Logo({ size = 48 }: { size?: number }) {
  const id = useId()
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" role="img" aria-label="LapRemote">
      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#5b6cff" />
          <stop offset="1" stopColor="#a855f7" />
        </linearGradient>
      </defs>
      <rect width="100" height="100" rx="22.5" fill={`url(#${id})`} />
      <rect x="24" y="25.2" width="52" height="49.6" rx="9" fill="none" stroke="#fff" strokeWidth="4.5" />
      <path d="M41.6 37 L41.6 63 L65.6 50 Z" fill="#fff" />
    </svg>
  )
}
